import sys

import pytest

from bst import BinarySearchTree

N = 5000


def _build(values):
    tree = BinarySearchTree()
    for v in values:
        tree.insert(v)
    return tree


@pytest.fixture(scope="module")
def ascending_tree():
    return _build(range(N))


@pytest.fixture(scope="module")
def descending_tree():
    return _build(range(N - 1, -1, -1))


def test_5000_ascending_inserts_no_recursion_error():
    tree = BinarySearchTree()
    for v in range(N):
        tree.insert(v)
    assert tree.inorder() == list(range(N))


def test_5000_descending_inserts_no_recursion_error():
    tree = BinarySearchTree()
    for v in range(N - 1, -1, -1):
        tree.insert(v)
    assert tree.inorder() == list(range(N))


def test_5000_ascending_inorder_equals_sorted_inserted(ascending_tree):
    assert ascending_tree.inorder() == sorted(range(N))


def test_5000_descending_inorder_equals_sorted_inserted(descending_tree):
    assert descending_tree.inorder() == sorted(range(N))


def test_5000_ascending_search_first_last_and_missing(ascending_tree):
    assert ascending_tree.search(0) is True
    assert ascending_tree.search(N - 1) is True
    assert ascending_tree.search(N) is False
    assert ascending_tree.search(-1) is False


def test_5000_descending_search_first_last_and_missing(descending_tree):
    assert descending_tree.search(0) is True
    assert descending_tree.search(N - 1) is True
    assert descending_tree.search(N) is False
    assert descending_tree.search(-1) is False


def test_5000_ascending_every_value_is_found(ascending_tree):
    for v in range(N):
        assert ascending_tree.search(v) is True


def test_5000_descending_every_value_is_found(descending_tree):
    for v in range(N):
        assert descending_tree.search(v) is True


def test_5000_descending_inserts_under_low_recursion_limit():
    def depth():
        d = 0
        f = sys._getframe()
        while f is not None:
            d += 1
            f = f.f_back
        return d

    old = sys.getrecursionlimit()
    sys.setrecursionlimit(depth() + 60)
    try:
        tree = _build(range(N - 1, -1, -1))
        assert tree.inorder() == list(range(N))
        assert tree.search(0) is True
        assert tree.search(N - 1) is True
        assert tree.search(N) is False
    finally:
        sys.setrecursionlimit(old)


def test_5000_ascending_inserts_under_low_recursion_limit():
    def depth():
        d = 0
        f = sys._getframe()
        while f is not None:
            d += 1
            f = f.f_back
        return d

    old = sys.getrecursionlimit()
    sys.setrecursionlimit(depth() + 60)
    try:
        tree = _build(range(N))
        assert tree.inorder() == list(range(N))
        assert tree.search(0) is True
        assert tree.search(N - 1) is True
        assert tree.search(-1) is False
    finally:
        sys.setrecursionlimit(old)


def test_inorder_on_5000_node_tree_returns_independent_copy(ascending_tree):
    first = ascending_tree.inorder()
    first.reverse()
    first.append(-1)
    assert ascending_tree.inorder() == list(range(N))


def test_criterion5_suite_runs_under_pytest():
    # Criterion 5: this module is executed by pytest; reaching this point
    # confirms collection and execution of the suite.
    assert BinarySearchTree().inorder() == []
